CREATE TABLE IF NOT EXISTS matters (tenant_id TEXT NOT NULL, matter_id TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (tenant_id, matter_id));
CREATE TABLE IF NOT EXISTS procedural_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, matter_id TEXT NOT NULL, event_type TEXT NOT NULL, event_date TEXT NOT NULL, source_id TEXT, status TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_procedural_events_scope ON procedural_events(tenant_id, matter_id, event_date);
CREATE TABLE IF NOT EXISTS discovery_objects (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, matter_id TEXT NOT NULL, kind TEXT NOT NULL, request_number TEXT, production_status TEXT NOT NULL, status TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_discovery_objects_scope ON discovery_objects(tenant_id, matter_id, kind, request_number);
CREATE TABLE IF NOT EXISTS filing_artifacts (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, matter_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, r2_key TEXT, blocked_reasons_json TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
